content.arguments:
{"plugin":{"kind":"new","idPrefix":"sample"},"name":"sequence Task probe","purpose":"Exercise Task validation from Host JavaScript","code":{"host":"
return {
  inject: ['developmentRooms', 'developmentTasks'],
  async apply(ctx) {
    const baseline = ctx.developmentTasks.list({ limit: 1 })[0]
    const participantId = 'cordis-artifact-source'
    const bindingId = 'cordis-artifact-binding'
    await ctx.developmentRooms.announce({ id: participantId, kind: 'agent', displayName: 'Artifact source' })
    await ctx.developmentTasks.checkout({ taskId: baseline.id, participantId, bindingId })
    const bound = ctx.developmentTasks.assignmentLog().at(-1)
    await ctx.developmentTasks.admitObservedContext({
      taskId: baseline.id, participantId, bindingId,
      expectedBindingEpoch: { nodeId: bound.nodeId, seq: bound.seq },
      sourceId: 'a'.repeat(64), text: 'Reject an exhausted artifact observation',
      observation: {
        kind: 'openapi-artifact', version: 1, artifactId: 'model-api', sourceName: 'checkout API',
        grantId: 'model-grant', sequence: Number.MAX_SAFE_INTEGER,
        operation: { method: 'post', path: '/orders' }, state: 'unavailable', reason: 'too-large',
      },
    })
  },
}
"}}

